        require(not pathlib.PurePosixPath(member.name).is_absolute() and all(x not in ('','.','..') for x in member.name.split('/')),'unsafe archive path')
        target=deployment/member.name
        canonical(target,absent=True)
        target.parent.mkdir(parents=True,exist_ok=True)
        raw=tar.extractfile(member).read()
        require(len(raw)==members[member.name]['bytes'] and hashlib.sha256(raw).hexdigest()==members[member.name]['sha256'],'A40 member differs')
        save(target,raw)
for name,item in members.items():
    bootstrap['raw_file'](deployment/name,item['sha256'])
